import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useSupabaseClient } from "@supabase/auth-helpers-react";

function OAuthHandler() {
  const supabase = useSupabaseClient();
  const navigate = useNavigate();

  useEffect(() => {
    const handleOAuth = async () => {
      try {
        // Parse the hash fragment to extract the token credentials
        const hash = window.location.hash.substring(1); // Remove the '#' character
        const params = new URLSearchParams(hash);

        const accessToken = params.get("access_token");
        const refreshToken = params.get("refresh_token");
        const expiresIn = params.get("expires_in");

        if (!accessToken || !refreshToken) {
          throw new Error("Missing token credentials in the URL hash.");
        }

        // Use Supabase to save the session
        const { data: session, error } = await supabase.auth.setSession({
          access_token: accessToken,
          refresh_token: refreshToken,
        });

        if (error) {
          console.error("Error saving session:", error.message);
          alert("Failed to log in. Please try again.");
          navigate("/#/"); // Navigate to the home page or error screen
          return;
        }

        console.log("OAuth session successfully established:", session);

        // Redirect to the desired post-login page
        navigate("/#/scheduler");
      } catch (error) {
        console.error("Error during OAuth handling:", error.message);
        alert("An error occurred during login.");
        navigate("/#/"); // Redirect to a fallback page
      } finally {
        // Cleanup the URL by removing the hash fragment
        window.history.replaceState(
          {},
          document.title,
          `${window.location.origin}/#/scheduler`
        );
      }
    };

    handleOAuth();
  }, [supabase, navigate]);

  return (
    <div style={{ textAlign: "center", marginTop: "50px" }}>
      <h2>Processing OAuth Login...</h2>
      <p>Please wait while we log you in.</p>
    </div>
  );
}

export default OAuthHandler;
