import { useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useSession } from "@supabase/auth-helpers-react";
import { FaCalendarAlt } from "react-icons/fa";
import "./Home.css";
import Particles from "react-tsparticles";
import { loadFull } from "tsparticles";

const Home = () => {
  const session = useSession();
  const navigate = useNavigate();
  useEffect(() => {
    if (session) {
      navigate(process.env.REACT_APP_REDIRECT_URL, { replace: true });
    }
  });
  const particlesInit = async (main) => {
    await loadFull(main);
  };

  return (
    <div className="min-h-screen flex flex-col justify-between bg-gradient-to-r from-purple-500 to-indigo-600 text-white">
      <Particles
        id="tsparticles"
        init={particlesInit}
        options={{
          background: {
            color: { value: "#000" },
          },
          particles: {
            number: { value: 100 },
            color: { value: "#ffffff" },
            links: {
              enable: true,
              distance: 150,
              color: "#ffffff",
              opacity: 0.4,
            },
            move: { enable: true, speed: 2 },
            size: { value: 3 },
          },
        }}
      />

      {/* Navigation Bar */}
      <header className="flex justify-between items-center p-6">
        <div className="text-3xl font-semibold">Aadit's Scheduling Tool</div>
        <nav>
          <Link to="/scheduler">
            <button className="bg-yellow-500 text-white py-2 px-4 rounded-lg shadow-md hover:bg-yellow-400 transition duration-300">
              <FaCalendarAlt className="inline-block mr-2" />
              TRY NOW
            </button>
          </Link>
        </nav>
      </header>

      {/* Hero Section */}
      <main className="flex flex-col items-center justify-center text-center space-y-6 p-8">
        <h1 className="text-5xl md:text-6xl font-extrabold leading-tight">
          Schedule Meetings <span className="text-yellow-500">Seamlessly</span>
        </h1>
        <p className="text-lg md:text-xl font-light text-gray-100">
          Experience effortless meeting scheduling with advanced tools and
          integrations.
        </p>
        <Link to="/scheduler">
          <button className="bg-yellow-500 text-white py-3 px-8 rounded-full text-lg shadow-xl hover:bg-yellow-400 transition duration-300">
            Get Started
          </button>
        </Link>
      </main>

      {/* Footer */}
      <footer className="text-center py-6 bg-indigo-700">
        <p className="text-sm">
          © 2024 Aadit's Scheduling Tool. All rights reserved.
        </p>
      </footer>
    </div>
  );
};

export default Home;
